using System.Security.Cryptography;
using System.Text;

namespace Rig.Core.Mail;

/// <summary>
/// Compiles the sweep plan into a Google Apps Script that runs it inside Gmail. Ported from <c>rig.mail.apps_script</c>.
/// Apps Script runs as the signed-in user with no Cloud project to create, and its batch calls take 100 threads at a
/// time, where the connector takes one. The generated file embeds real queries, so write it under <c>temp/</c>: it is
/// data, not source.
/// </summary>
public static class AppsScript
{
    // Kept byte for byte as the Python held it; the closing newline is added in Render.
    private const string Template = """"
// Generated by `uv run mail apps-script`. Do not edit: change the rules and regenerate.
//
// Setup: script.google.com → New project → paste this file over Code.gs → Save.
// Pick `setup` in the function dropdown (it is first, so it is the default after a reload).
// Then run `setup`, read the execution log, and keep running `setup` until it says
// "All set". Each run does the next step and says exactly what to do. Nothing changes
// in Gmail until you have seen a preview and run `setup` again.
//
// Changed the rules? Regenerate, paste over this file, run `setup`: it notices the new
// version, previews again, and replaces only the filters it created.
//
// Other entry points: `dryRun` (preview only), `triage` (apply rules now),
// `syncFilters`, `installTrigger` / `removeTrigger` (triage every 15 minutes).

const VERSION = '__VERSION__';
const STEPS = __STEPS__;
const FILTERS = __FILTERS__;
const BATCH = 100;
const BUDGET_MS = 5 * 60 * 1000;
const COUNT_CAP = 5000;

function setup() {
  const props = PropertiesService.getUserProperties();
  const say = (line) => console.log(line);
  if (typeof Gmail === 'undefined') {
    say('STEP 1 of 4: add the Gmail service (lets this script create filters).');
    say('  Left sidebar → Services (+) → pick "Gmail API" → Add. Then run setup again.');
    return;
  }
  say('✓ Gmail service added');
  if (props.getProperty('previewed') !== VERSION) {
    say('STEP 2 of 4: preview. NOTHING HAS BEEN CHANGED. Threads each rule would touch now:');
    dryRun();
    props.setProperty('previewed', VERSION);
    say('If those numbers look right, run setup again: it creates the filters and starts');
    say('clearing the backlog. If one looks too big, stop here and fix that rule.');
    return;
  }
  say('✓ Preview seen');
  if (props.getProperty('filtersFor') !== VERSION) {
    say('STEP 3 of 4: creating filters for new mail…');
    const failed = syncFilters();
    if (failed) {
      // Not recorded as synced, so the next setup run retries (it replaces only its own filters).
      say(`⚠ ${failed} filter(s) were not created: see the NOT created lines above. The next`);
      say('  setup run retries. If an identical filter already exists (say from an XML import),');
      say('  delete that one in Gmail settings so this script can own it.');
    } else {
      props.setProperty('filtersFor', VERSION);
      say('✓ Filters done (Gmail → Settings → Filters and Blocked Addresses lists them)');
    }
  } else {
    say('✓ Filters done (Gmail → Settings → Filters and Blocked Addresses lists them)');
  }
  say('STEP 3 of 4: clearing the backlog…');
  if (!triage()) {
    say('Backlog not finished yet: run setup again (each run works for ~5 minutes).');
    return;
  }
  say('✓ Backlog clear');
  const scheduled = ScriptApp.getProjectTriggers().some((t) => t.getHandlerFunction() === 'triage');
  if (scheduled) {
    say('✓ Scheduled triage on (run removeTrigger to stop it)');
  } else {
    say('STEP 4 of 4 (optional): run installTrigger so age-based rules (older_than) apply');
    say('  every 15 minutes. Filters already handle everything else as it arrives.');
  }
  say('All set.');
}

function triage() {
  const started = Date.now();
  const deadline = started + BUDGET_MS;
  const secs = () => Math.round((Date.now() - started) / 1000) + 's';
  const labels = {};
  const fast = typeof Gmail !== 'undefined';
  const ids = fast ? labelIds_() : {};
  const mode = fast ? 'Gmail API, up to 1000 per call' : 'GmailApp, 100 per call: add the Gmail service for speed';
  console.log(`triage ${VERSION}: ${STEPS.length} rules, ${mode}, stops after ${BUDGET_MS / 60000} min`);
  for (const [i, step] of STEPS.entries()) {
    const label = step.label ? ensureLabel_(labels, step.label) : null;
    let result = null;
    if (fast && !step.trash) {
      if (step.label && !ids[step.label]) Object.assign(ids, labelIds_());
      try {
        result = fastStep_(step, step.label ? ids[step.label] : null, deadline, secs);
      } catch (e) {
        console.log(`  ${step.rule}: Gmail API refused (${e.message}); using the slow path`);
      }
    }
    if (!result) result = slowStep_(step, label, deadline, secs);
    const note = result.skipped ? `, ${result.skipped} skipped` : result.done ? '' : ' (nothing to do)';
    console.log(`[${i + 1}/${STEPS.length}] ${step.rule}: ${result.done} ${result.unit}${note}`);
    if (Date.now() >= deadline) {
      const left = STEPS.slice(i).map((s) => s.rule).join(', ');
      console.log(`Time budget used after ${secs()}. Not finished: ${left}. Run again to continue.`);
      return false;
    }
  }
  console.log(`All rules up to date (${secs()}).`);
  return true;
}

// Fast path: list matching message IDs and change them with batchModify, 1000 per call.
// Messages, not threads, as Gmail filters do: a person's reply in the same thread is untouched.
function fastStep_(step, labelId, deadline, secs) {
  const add = [labelId, step.star ? 'STARRED' : null, step.important === true ? 'IMPORTANT' : null];
  const remove = [step.archive ? 'INBOX' : null, step.mark_read ? 'UNREAD' : null,
    step.important === false ? 'IMPORTANT' : null];
  add.splice(0, add.length, ...add.filter(Boolean));
  remove.splice(0, remove.length, ...remove.filter(Boolean));
  const handled = new Set();
  let done = 0;
  let pageToken;
  while (Date.now() < deadline) {
    const page = Gmail.Users.Messages.list('me', { q: step.query, maxResults: 500, pageToken });
    const ids = (page.messages || []).map((m) => m.id).filter((id) => !handled.has(id));
    if (ids.length === 0) {
      // Every sweep query excludes finished mail, so a page of handled IDs means no progress.
      if (!page.nextPageToken) break;
      pageToken = page.nextPageToken;
      continue;
    }
    Gmail.Users.Messages.batchModify({ ids, addLabelIds: add, removeLabelIds: remove }, 'me');
    ids.forEach((id) => handled.add(id));
    done += ids.length;
    pageToken = undefined; // changed mail drops out of the query, so start again from the top
    console.log(`  ${step.rule}: +${ids.length} (${done} so far, ${secs()})`);
  }
  return { done, skipped: 0, unit: 'messages' };
}

// Slow path: GmailApp, 100 threads per call. Used without the Gmail service, for trash, or
// when the API refuses a rule.
function slowStep_(step, label, deadline, secs) {
  let done = 0;
  const skipped = new Set();
  const handled = new Set();
  while (Date.now() < deadline) {
    // Threads Gmail refused stay matched, so page past them rather than re-fetching them.
    const found = GmailApp.search(step.query, skipped.size, BATCH);
    const threads = found.filter((t) => !skipped.has(t.getId()));
    // Every sweep query excludes finished threads; seeing them again means no progress.
    if (threads.length === 0 || threads.every((t) => handled.has(t.getId()))) break;
    const refused = apply_(step, label, threads);
    refused.forEach((id) => skipped.add(id));
    threads.forEach((t) => handled.add(t.getId()));
    done += threads.length - refused.length;
    console.log(`  ${step.rule}: +${threads.length - refused.length} (${done} so far, ${secs()})`);
    if (found.length < BATCH && refused.length === threads.length) break;
  }
  return { done, skipped: skipped.size, unit: 'threads' };
}

function labelIds_() {
  const ids = {};
  (Gmail.Users.Labels.list('me').labels || []).forEach((l) => { ids[l.name] = l.id; });
  return ids;
}

// Apply a step to a batch. Gmail rejects a whole batch if any one thread cannot be
// changed ("Gmail operation not allowed"), so on failure retry thread by thread and
// return the IDs that still fail, logging enough to find them.
function apply_(step, label, threads) {
  const act = (ts) => {
    if (label) label.addToThreads(ts);
    if (step.star) ts.forEach((t) => t.getMessages().forEach((m) => m.star()));
    if (step.mark_read) GmailApp.markThreadsRead(ts);
    if (step.important === true) GmailApp.markThreadsImportant(ts);
    if (step.important === false) GmailApp.markThreadsUnimportant(ts);
    if (step.trash) GmailApp.moveThreadsToTrash(ts);
    else if (step.archive) GmailApp.moveThreadsToArchive(ts);
  };
  try {
    act(threads);
    return [];
  } catch (e) {
    console.log(`  ${step.rule}: batch refused (${e.message}); retrying one at a time`);
  }
  const refused = [];
  for (const t of threads) {
    try {
      act([t]);
    } catch (e) {
      refused.push(t.getId());
      console.log(`  skipped "${t.getFirstMessageSubject()}" ${t.getPermalink()} - ${e.message}`);
    }
  }
  return refused;
}

function dryRun() {
  for (const step of STEPS) {
    let count = 0;
    while (count < COUNT_CAP) {
      const page = GmailApp.search(step.query, count, 500).length;
      count += page;
      if (page < 500) break;
    }
    console.log(`${step.rule}: ${count >= COUNT_CAP ? COUNT_CAP + '+' : count} threads  [${step.query}]`);
  }
}

function syncFilters() {
  if (typeof Gmail === 'undefined') {
    throw new Error('Add the Gmail API service first: Services (+) → Gmail API → Add.');
  }
  const props = PropertiesService.getUserProperties();
  const managed = JSON.parse(props.getProperty('managedFilterIds') || '[]');
  const existing = new Set((Gmail.Users.Settings.Filters.list('me').filter || []).map((f) => f.id));
  for (const id of managed) {
    if (existing.has(id)) Gmail.Users.Settings.Filters.remove('me', id);
  }
  const cache = {};
  FILTERS.forEach((f) => { if (f.label) ensureLabel_(cache, f.label); });
  const ids = labelIds_();
  const created = [];
  for (const f of FILTERS) {
    const criteria = {};
    if (f.sender) criteria.from = f.sender;
    if (f.to) criteria.to = f.to;
    if (f.subject) criteria.subject = f.subject;
    if (f.query) criteria.query = f.query;
    if (f.negated_query) criteria.negatedQuery = f.negated_query;
    const add = f.label ? [ids[f.label], ...f.add] : [...f.add];
    const action = {};
    if (add.length) action.addLabelIds = add;
    if (f.remove.length) action.removeLabelIds = [...f.remove];
    try {
      created.push(Gmail.Users.Settings.Filters.create({ criteria, action }, 'me').id);
      console.log(`${f.rule}: filter created`);
    } catch (e) {
      console.log(`${f.rule}: NOT created - ${e.message}`);
    }
  }
  props.setProperty('managedFilterIds', JSON.stringify(created));
  console.log(`${created.length}/${FILTERS.length} filters in place.`);
  return FILTERS.length - created.length;
}

function installTrigger() {
  removeTrigger();
  ScriptApp.newTrigger('triage').timeBased().everyMinutes(15).create();
  console.log('triage now runs every 15 minutes.');
}

function removeTrigger() {
  ScriptApp.getProjectTriggers()
    .filter((t) => t.getHandlerFunction() === 'triage')
    .forEach((t) => ScriptApp.deleteTrigger(t));
}

function ensureLabel_(cache, name) {
  if (cache[name]) return cache[name];
  const parts = name.split('/');
  let label = null;
  for (let i = 1; i <= parts.length; i++) {
    const path = parts.slice(0, i).join('/');
    label = GmailApp.getUserLabelByName(path) || GmailApp.createLabel(path);
  }
  cache[name] = label;
  return label;
}
"""";

    /// <summary>A self-contained Apps Script whose <c>setup</c> walks the user through every step.</summary>
    public static string Render(IEnumerable<SweepStep> steps, IEnumerable<ApiFilter> filters)
    {
        var stepsJson = MailExport.SweepJson(steps);
        var filtersJson = MailExport.ApiFiltersJson(filters);
        var version = Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(stepsJson + filtersJson)))[..12];
        // A Windows checkout may hold the template with CRLF endings; the script is always LF, as the Python wrote it.
        return (Template.Replace("\r\n", "\n", StringComparison.Ordinal) + "\n")
            .Replace("__VERSION__", version, StringComparison.Ordinal)
            .Replace("__STEPS__", stepsJson, StringComparison.Ordinal)
            .Replace("__FILTERS__", filtersJson, StringComparison.Ordinal);
    }
}
